/* Apply font kerning for improved visual balance */
h1, .display-text {
  font-kerning: normal; /* Enables kerning based on font data */
  /* 'auto' (default) allows browser to decide, 'none' disables it. */
}

/* Example of disabling kerning for specific elements if needed */
.no-kerning {
  font-kerning: none;
}
